{
  "units": [
    {
      "quote": "An applicant with a pending name change must not be issued a passport in her/his new name.",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "prohibition",
      "meaning": "When a name change court order or decree is not final and the name change is pending, a passport must not be issued to the applicant in their new name."
    },
    {
      "quote": "See 8 FAM 1001.5 regarding applying for a replacement passport in a new name;",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "background",
      "meaning": "Cross-references 8 FAM 1001.5 for procedures regarding applying for a replacement passport in a new name, carrying no independent operational mandate."
    },
    {
      "quote": "An applicant with a pending name change must not be issued a form FS-240 in her/his new name.",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "prohibition",
      "meaning": "When a name change court order or decree is not final and the name change is pending, a Form FS-240 must not be issued to the applicant in their new name."
    },
    {
      "quote": "See 8 FAM 1001.3 regarding amending a form FS-240; and",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "background",
      "meaning": "Cross-references 8 FAM 1001.3 for procedures regarding amending a Form FS-240, carrying no independent operational mandate."
    },
    {
      "quote": "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time.",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "requirement",
      "meaning": "The adjudicator must clear the applicant's pending name, notwithstanding that the name change is not final and regardless of whether the passport is currently being issued."
    },
    {
      "quote": "The court order or decree must list both the applicant's current and former name(s).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "The court order or decree submitted for a name change is required to list both the applicant's current name and former name(s)."
    },
    {
      "quote": "You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program).",
      "scope_quotes": ["EXCEPTION:"],
      "kind": "statement",
      "meaning": "Acknowledges that an adjudicator may receive a court order where the applicant's former name is made confidential under programs such as California's Safe at Home program."
    },
    {
      "quote": "When this occurs, the applicant must provide both her/his current and former names on the application.",
      "scope_quotes": [
        "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
      ],
      "kind": "requirement",
      "meaning": "When a court order renders the former name confidential, the applicant is obligated to provide both their current and former names on the passport application."
    },
    {
      "quote": "You may request additional evidence of U.S. citizenship/non-citizen U.S. nationality or identity in accordance with 22 CFR 51.23 and 22 CFR 51.45.",
      "scope_quotes": [
        "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."
      ],
      "kind": "permission",
      "meaning": "When a court order makes the former name confidential, the adjudicator is permitted to request additional proof of U.S. citizenship, non-citizen U.S. nationality, or identity pursuant to 22 CFR 51.23 and 22 CFR 51.45."
    },
    {
      "quote": "8 FAM 403.1-3(B) Name Spacing\n\n(CT:CITZ-96; 08-04-2023)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Section title and editorial/revision metadata providing no substantive rules."
    },
    {
      "quote": "In accordance with International Civil Aviation Organization (ICAO) recommendations, U.S. passports, form FS-240, and form DS-2060 are printed in all uppercase letters. Printing a name with multiple parts in uppercase letters causes the name to appear as one word unless the parts are separated with spaces.",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Explains context and printing practice under ICAO standards leading to names appearing as one word if not spaced, serving as factual background for the spacing rules."
    },
    {
      "quote": "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If an applicant has a multi-part name, the adjudicator is required to determine how the name will be formatted and spaced."
    },
    {
      "quote": "If the applicant's previous passport had a space, you should add a space on the current application;",
      "scope_quotes": [
        "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "kind": "recommendation",
      "meaning": "For a multi-part name, if the applicant's previous passport included a space, the adjudicator should include a space on the current application."
    },
    {
      "quote": "If the applicant does not have a previous passport and the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality or ID has a space, you should add a space on the current application; or",
      "scope_quotes": [
        "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "kind": "recommendation",
      "meaning": "For a multi-part name, if the applicant has no prior passport and their citizenship/nationality evidence or ID contains a space, the adjudicator should include a space on the current application."
    },
    {
      "quote": "If the applicant expresses a clear preference to add or remove space, either verbally or in writing, you may add or remove it per the applicant's preference.",
      "scope_quotes": [
        "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "kind": "permission",
      "meaning": "For a multi-part name, if the applicant states a clear preference (verbally or in writing) to insert or delete a space, the adjudicator is authorized to add or remove it according to that preference."
    },
    {
      "quote": "If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "When processing applications from multiple family members, the adjudicator should maintain consistent spacing across their last names, except when an individual family member explicitly requests a different spacing."
    },
    {
      "quote": "unless a family member expresses a clear preference for a different spacing.",
      "scope_quotes": [
        "NOTE: If you receive applications from several family members, you should space the last names consistently,"
      ],
      "kind": "exception",
      "meaning": "Provides an exception to the consistent spacing recommendation among family members when a family member clearly indicates a preference for differing spacing."
    },
    {
      "quote": "For special-issuance passports, the spacing of an eligible family member's last name should match the spacing of the last name of the sponsor.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In the case of special-issuance passports, the last name spacing of an eligible family member should be formatted to match the spacing of the sponsor's last name."
    },
    {
      "quote": "Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Discrepancies or issues regarding name spacing generally do not justify rewriting a passport, except when the Department failed to follow an applicant's clearly expressed preference."
    },
    {
      "quote": "unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [
        "b. Name spacing issues are generally not sufficient cause to rewrite a passport,"
      ],
      "kind": "exception",
      "meaning": "Establishes an exception allowing a passport rewrite for name spacing issues if the Department disregarded a clear preference expressed by the applicant."
    },
    {
      "quote": "Arabic ordinal numbers must be changed to Roman numerals, for example, 2nd to II, 3rd to III:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Arabic ordinal numbers appearing in names must be converted to Roman numerals (e.g., converting '2nd' to 'II' and '3rd' to 'III')."
    },
    {
      "quote": "Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Observes that some applicants might use the prefix 'Sr.' as a Spanish abbreviation for 'Señor' ('Mr.' or 'Mister')."
    },
    {
      "quote": "If you determine that this is the case, follow the guidance in 8 FAM 403.1-5(C) regarding ranks and titles.",
      "scope_quotes": [
        "d. Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English."
      ],
      "kind": "requirement",
      "meaning": "If the adjudicator determines that 'Sr.' is used as an abbreviation for 'Señor', they must follow the ranks and titles procedures detailed in 8 FAM 403.1-5(C)."
    },
    {
      "quote": "Name suffix issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Issues relating to name suffixes generally do not constitute sufficient grounds to rewrite a passport, except in instances where the Department failed to respect the applicant's clear preference."
    },
    {
      "quote": "unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [
        "e. Name suffix issues are generally not sufficient cause to rewrite a passport,"
      ],
      "kind": "exception",
      "meaning": "Establishes an exception allowing a passport rewrite for name suffix issues when the Department failed to adhere to the applicant's clear preference."
    }
  ]
}
